// Examples:
// >>> sort_mixed_list([19,'red',12,'green','blue', 10,'white','green',1])
// >>> [1, 10, 12, 19, 'blue', 'green', 'green', 'red', 'white']
// >>> sort_mixed_list([19,'red',12,'green','blue', 10,'white','green',1])
// >>> [1, 10, 12, 19, 'blue', 'green', 'green', 'red', 'white']
// >>> sort_mixed_list([19,'red',12,'green','blue', 10,'white','green',1])
// >>> [1, 10, 12, 19, 'blue', 'green', 'green', 'red', 'white']
func sort_mixed_list (mixed_list []interface{}) []interface{} {
	var int_list []int
	var str_list []string
	for _, v := range mixed_list {
		switch v.(type) {
		case int:
			int_list = append(int_list, v.(int))
		case string:
			str_list = append(str_list, v.(string))
		}
	}
	sort.Ints(int_list)
	sort.Strings(str_list)
	var result []interface{}
	result = append(result, int_list...)
	result = append(result, str_list...)
	return result
}

