// Code should be written in Go/Golang
// Write a function to sort the given array by using counting sort.
// Examples:
// >>> counting_sort([1,23,4,5,6,7,8])
// >>> [1, 4, 5, 6, 7, 8, 23]
// >>> counting_sort([12, 9, 28, 33, 69, 45])
// >>> [9, 12, 28, 33, 45, 69]
// >>> counting_sort([8, 4, 14, 3, 2, 1])
// >>> [1, 2, 3, 4, 8, 14]
func counting_sort (my_list []int) []int {
	// your code goes here
	max := my_list[0]
	for _, v := range my_list {
		if v > max {
			max = v
		}
	}
	count := make([]int, max+1)
	for _, v := range my_list {
		count[v]++
	}
	for i := 1; i < len(count); i++ {
		count[i] += count[i-1]
	}
	sorted := make([]int, len(my_list))
	for i := len(my_list)-1; i >= 0; i-- {
		sorted[count[my_list[i]]-1] = my_list[i]
		count[my_list[i]]--
	}
	return sorted
}

