// Code should be written in Go/Golang
// Write a function to find the number of ways to partition a set of bell numbers.
// Examples:
// >>> bell_number(2)
// >>> 2
// >>> bell_number(10)
// >>> 115975
// >>> bell_number(56)
// >>> 6775685320645824322581483068371419745979053216268760300
func bell_number (n int) int {
	// your code goes here
	return int(bell_number_rec(n, make(map[int]int)))
}

func bell_number_rec(n int, dp map[int]int) int {
	if n == 0 {
		return 1
	}
	if v, ok := dp[n]; ok {
		return v
	}
	v := 0
	for i := 1; i <= n; i++ {
		v += bell_number_rec(i-1, dp) * bell_number_rec(n-i, dp)
	}
	dp[n] = v
	return v
}

