// >>> comb_sort([41, 32, 15, 19, 22])
// >>> [15, 19, 22, 32, 41]
// >>> comb_sort([99, 15, 13, 47])
// >>> [13, 15, 47, 99]
func comb_sort (nums []int) []int {
	// your code goes here
	for gap := len(nums); gap > 1; gap = int(float64(gap) / 1.3) {
		for i := 0; i+gap < len(nums); i++ {
			if nums[i] > nums[i+gap] {
				nums[i], nums[i+gap] = nums[i+gap], nums[i]
			}
		}
	}
	return nums
}

