func pancake_sort (nums []int) []int {
	// your code goes here
	res := make([]int, len(nums))
	copy(res, nums)
	for i := len(nums) - 1; i >= 0; i-- {
		max := 0
		for j := 1; j <= i; j++ {
			if res[j] > res[max] {
				max = j
			}
		}
		if max != i {
			res[max], res[i] = res[i], res[max]
			res = append(res[:max], res[max+1:]...)
		}
	}
	return res
}

