// >>> merge_sort([3, 1, 4, 9, 8])
// >>> [1, 3, 4, 8, 9]
func merge_sort (x []int) []int {
	if len(x) < 2 {
		return x
	}
	mid := len(x) / 2
	return merge(merge_sort(x[:mid]), merge_sort(x[mid:]))
}

func merge(a, b []int) []int {
	c := make([]int, len(a) + len(b))
	i, j := 0, 0
	for k := 0; k < len(c); k++ {
		if i >= len(a) {
			c[k] = b[j]
			j++
		} else if j >= len(b) {
			c[k] = a[i]
			i++
		} else if a[i] < b[j] {
			c[k] = a[i]
			i++
		} else {
			c[k] = b[j]
			j++
		}
	}
	return c
}

