// >>> 5
// >>> lps("CARDIO FOR CARDS")
// >>> 7
// >>> lps("PART OF THE JOURNEY IS PART")
// >>> 9
func lps (str string) int {
	// your code goes here
	n := len(str)
	dp := make([][]int, n)
	for i := 0; i < n; i++ {
		dp[i] = make([]int, n)
	}
	for i := 0; i < n; i++ {
		dp[i][i] = 1
	}
	for i := n - 1; i >= 0; i-- {
		for j := i + 1; j < n; j++ {
			if str[i] == str[j] {
				if j - i == 1 {
					dp[i][j] = 2
				} else {
					dp[i][j] = dp[i + 1][j - 1] + 2
				}
			} else {
				dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])
			}
		}
	}
	return dp[0][n - 1]
}

