// Code should be written in Go/Golang
// Write a function to sort the given array by using shell sort.
// Examples:
// >>> shell_sort([12, 23, 4, 5, 3, 2, 12, 81, 56, 95])
// >>> [2, 3, 4, 5, 12, 12, 23, 56, 81, 95]
// >>> shell_sort([24, 22, 39, 34, 87, 73, 68])
// >>> [22, 24, 34, 39, 68, 73, 87]
// >>> shell_sort([32, 30, 16, 96, 82, 83, 74])
// >>> [16, 30, 32, 74, 82, 83, 96]
func shell_sort (my_list []int) []int {
	for gap := len(my_list) / 2; gap > 0; gap /= 2 {
		for i := gap; i < len(my_list); i++ {
			temp := my_list[i]
			j := i
			for j >= gap && my_list[j - gap] > temp {
				my_list[j] = my_list[j - gap]
				j -= gap
			}
			my_list[j] = temp
		}
	}
	return my_list
}

