			if price[i] > price[i-1] {
				max += price[i] - price[i-1]
			}
		}
		return max
	}
	var dp [][]int
	for i := 0; i <= k; i++ {
		dp = append(dp, make([]int, n))
	}
	for i := 1; i < n; i++ {
		for j := 1; j <= k; j++ {
			dp[j][i] = max(dp[j][i-1], dp[j-1][i-1]+price[i]-price[i-1])
		}
	}
	return dp[k][n-1]
