// Code should be written in Go/Golang
// Write a function to sort a list of elements using radix sort.
// Examples:
// >>> radix_sort([15, 79, 25, 68, 37])
// >>> [15, 25, 37, 68, 79]
// >>> radix_sort([9, 11, 8, 7, 3, 2])
// >>> [2, 3, 7, 8, 9, 11]
// >>> radix_sort([36, 12, 24, 26, 29])
// >>> [12, 24, 26, 29, 36]
func radix_sort (nums []int) []int {
	// your code goes here
	m := make(map[int]int)
	for _, v := range nums {
		m[v] = 1
	}
	var keys []int
	for k := range m {
		keys = append(keys, k)
	}
	sort.Ints(keys)
	res := make([]int, len(nums))
	for i := 0; i < len(keys); i++ {
		for j := 0; j < len(nums); j++ {
			if nums[j] == keys[i] {
				res[i] = nums[j]
				break
			}
		}
	}
	return res
}

