// Code should be written in Go/Golang
// Write a function to find the longest bitonic subsequence for the given array.
// Examples:
// >>> lbs([0 , 8 , 4, 12, 2, 10 , 6 , 14 , 1 , 9 , 5 , 13, 3, 11 , 7 , 15])
// >>> 7
// >>> lbs([1, 11, 2, 10, 4, 5, 2, 1])
// >>> 6
// >>> lbs([80, 60, 30, 40, 20, 10])
// >>> 5
func lbs (arr []int) int {
	// your code goes here
	n := len(arr)
	if n == 1 {
		return 1
	}
	dp := make([][]int, n)
	for i := 0; i < n; i++ {
		dp[i] = make([]int, n)
	}
	for i := 1; i < n; i++ {
		for j := 0; j < i; j++ {
			if arr[i] > arr[j] {
				dp[i][j] = 1 + dp[j][j]
			} else {
				dp[i][j] = 1
			}
			if dp[i][j] > dp[i][i] {
				dp[i][i] = dp[i][j]
			}
		}
	}
	max := 0
	for i := 0; i < n; i++ {
		if dp[i][i] > max {
			max = dp[i][i]
		}
	}
	return max
}

