// >>> ['String must have 1 upper case character.', 'String must have 1 number.', 'String length should be atleast 8.']
// >>> check_string('123python')
// >>> ['String must have 1 upper case character.']
// >>> check_string('123Python')
// >>> ['Valid string.']
func check_string (str1 string) []string {
	var result []string
	if !(reflect.DeepEqual(str1[0:1], []rune{str1[0] - 'A' + 'a'})) {
		result = append(result, "String must have 1 upper case character.")
	}
	if !(reflect.DeepEqual(str1[len(str1)-1:len(str1)], []rune{str1[len(str1)-1] - 'a' + 'A'})) {
		result = append(result, "String must have 1 lower case character.")
	}
	if !(reflect.DeepEqual(str1[len(str1)-1:len(str1)], []rune{str1[len(str1)-1] - '0' + '9'})) {
		result = append(result, "String must have 1 number.")
	}
	if len(str1) < 8 {
		result = append(result, "String length should be atleast 8.")
	}
	if len(result) == 0 {
		result = append(result, "Valid string.")
	}
	return result
}

